('indochina-country-profiles','লাওস ও তিমুর-লেস্তে','laos-timor-leste-reference','546','2'),
('myanmar-rohingya-reference','মিয়ানমার','myanmar-reference','547','1'),
('myanmar-rohingya-reference','রোহিঙ্গা সমস্যা','rohingya-reference','548','2')) x(chapter_slug,title,slug,page,ord) JOIN public.chapters c ON c.slug=x.chapter_slug AND c.book_id=(SELECT id FROM public.books WHERE title='Jubayer''s GK' LIMIT 1) WHERE NOT EXISTS (SELECT 1 FROM public.topics t WHERE t.chapter_id=c.id AND t.slug=x.slug);
