INSERT INTO public.fact_verifications (source_page,entity_type,entity_id,claim_text,normalized_claim,verification_status,confidence,verification_sources,audit_note) SELECT 544,'note',(SELECT id FROM public.gk_notes WHERE canonical_hash='4a3fcc9daf0e7ee474c2cceca10fbededae1b9c517a0e0d4c2d9ee2c93dd014e' LIMIT 1),'উৎসে থাইল্যান্ডের ‘মুক্তভূমি’ অর্থ, সিয়াম নাম, সাদা হাতির উপনাম, বৌদ্ধ পরিচয়, দ্বিতীয় বিশ্বযুদ্ধের সময় জাপানি দখল, রাজনৈতিক আন্দোলন, নারী প্রধানমন্ত্রী এবং বাধ্যতামূলক ভোটের কথা আছে।
INSERT INTO public.fact_verifications (source_page,entity_type,entity_id,claim_text,normalized_claim,verification_status,confidence,verification_sources,audit_note) SELECT 545,'note',(SELECT id FROM public.gk_notes WHERE canonical_hash='c17da1320737445927c83753b07757c79b1c946032ae4de1994208aa8c6f5f2e' LIMIT 1),'উৎসে ভিয়েতনামের দ্বিতীয় বিশ্বযুদ্ধ, ইন্দোচীন যুদ্ধ, ১৯৫৪ বিভাজন, ১৯৭৬ একত্রীকরণ, হো চি মিন এবং সায়গন/হো চি মিন সিটি সম্পর্কিত তথ্য আছে।
