INSERT INTO public.fact_verifications (source_page,entity_type,entity_id,claim_text,normalized_claim,verification_status,confidence,verification_sources,audit_note) SELECT 546,'note',(SELECT id FROM public.gk_notes WHERE canonical_hash='c7e116ecb7ce0c9e22121923a0656aec94ce7792de73a7e225742045739c21c7' LIMIT 1),'উৎসে লাওসের একদলীয় কমিউনিস্ট রাষ্ট্রব্যবস্থা, লাওসিয়ান পরিচয় এবং ফরাসি ইন্দোচীন সম্পর্ক আছে। তিমুর-লেস্তে অংশে ১৯৭৫ ঘোষণা, ইন্দোনেশীয় দখল, ১৯৯৯ গণভোট, ২০০২ স্বাধীনতা, ফ্রেটিলিন ও পূর্ব/পশ্চিম তিমুরের তথ্য রয়েছে।
