('548','myanmar-rohingya-reference','rohingya-reference','রোহিঙ্গা, ARSA ও আনান কমিশন — উৎস-সময়ভিত্তিক নোট','উৎসে রোহিঙ্গা নাগরিকত্ব, ২০১৭ সামরিক অভিযান, ১৯৭৮ আগমন, ARSA, আনান কমিশন এবং মিয়ানমারের সাংবিধানিক পরিবর্তনের বর্ণনা রয়েছে।
সতর্কতা | ১৯৮২ নাগরিকত্ব আইন, ২০১৭ অভিযানের ভাষা, সরকারি ARSA শ্রেণিবিন্যাস এবং সাংবিধানিক ব্যাখ্যাগুলো source-attributed হিসেবে রাখা হয়েছে; সেগুলোকে স্বতন্ত্র বর্তমান বা আইনি সিদ্ধান্ত হিসেবে উপস্থাপন করা হয়নি। ‘মাও মাও’, স্থানীয় ARSA নাম এবং চলচ্চিত্র-নির্মাতার লাইন withheld রাখা হয়েছে।','medium','9053769fea400009fd2e24e1e0f44087bd667b9179b42e7caab3800e2cf3a27a'),
('548','myanmar-rohingya-reference','rohingya-reference','মিয়ানমারের সাংবিধানিক পরিবর্তন — উৎস-সংক্ষিপ্তসার','উৎসে ২০০৮ সালের নতুন সংবিধান, ‘Republic of the Union of Myanmar’ নাম, ইয়াঙ্গুন থেকে নৈপিদোতে রাজধানী স্থানান্তর এবং প্রধানমন্ত্রীর পদ বাতিল করে উপ-রাষ্ট্রপতি পদ প্রতিষ্ঠার বর্ণনা রয়েছে।
সতর্কতা | এই রাজনৈতিক ও প্রাতিষ্ঠানিক উপাদানগুলো উৎস-সময়ের, এবং শহরের বাংলা বানান স্ক্যানে ভিন্ন; তাই আলাদা বর্তমান fact হিসেবে স্বাভাবিকীকরণ করা হয়নি।','medium','79a2b84f88d7e314bdd9607c23b42c8fca5b98f2915ba63605617439bbb2f091')) INSERT INTO public.gk_notes (book_id,chapter_id,topic_id,title,content,source_page,source_section,display_order,confidence,canonical_hash) SELECT b.id,c.id,t.id,d.title,d.body,d.page::integer,d.title,d.page::integer,d.confidence::confidence_level,d.hash FROM d JOIN public.books b ON b.title='Jubayer''s GK' JOIN public.chapters c ON c.book_id=b.id AND c.slug=d.chapter_slug JOIN public.topics t ON t.chapter_id=c.id AND t.slug=d.topic_slug ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;
